ticle only.","tree":{"sha":"2abc6e4c5ae386b7c591e4438e33b7518eacecb2","url":"https://api.github.com/repos/samakshrastogi/SK-Central/git/trees/2abc6e4c5ae386b7c591e4438e33b7518eacecb2"},"url":"https://api.github.com/repos/samakshrastogi/SK-Central/git/commits/3b3e275680269acaca4199b3ff196a87593b9ad9","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/124247791?v=4","events_url":"https://api.github.com/users/samakshrastogi/events{/privacy}","followers_url":"https://api.github.com/users/samakshrastogi/followers","following_url":"https://api.github.com/users/samakshrastogi/following{/other_user}","gists_url":"https://api.github.com/users/samakshrastogi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/samakshrastogi","id":124247791,"login":"samakshrastogi","node_id":"U_kgDOB2fe7w","organizations_url":"https://api.github.com/users/samakshrastogi/orgs","received_events_url":"https://api.github.com/users/samakshrastogi/received_events","repos_url":"https://api.github.com/users/samakshrastogi/repos","site_admin":false,"starred_url":"https://api.github.com/users/samakshrastogi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/samakshrastogi/subscriptions","type":"User","url":"https://api.github.com/users/samakshrastogi","user_view_type":"public"},"html_url":"https://github.com/samakshrastogi/SK-Central/commit/3b3e275680269acaca4199b3ff196a87593b9ad9","node_id":"C_kwDOTSWPsdoAKDNiM2UyNzU2ODAyNjlhY2FjYTQxOTliM2ZmMTk2YTg3NTkzYjlhZDk","parents":[{"html_url":"https://github.com/samakshrastogi/SK-Central/commit/82cb1790cc2f9f17ca6a2a2393b627e1ed9e0e3a","sha":"82cb1790cc2f9f17ca6a2a2393b627e1ed9e0e3a","url":"https://api.github.com/repos/samakshrastogi/SK-Central/commits/82cb1790cc2f9f17ca6a2a2393b627e1ed9e0e3a"}],"sha":"3b3e275680269acaca4199b3ff196a87593b9ad9","url":"https://api.github.com/repos/samakshrastogi/SK-Central/c