m>","tree":{"sha":"8a843588844e5ef32cd32610305032bb8a06dffc","url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/git/trees/8a843588844e5ef32cd32610305032bb8a06dffc"},"url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/git/commits/2fb0259a35fd83a9e50f2b38b3667f5056811359","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/511761?v=4","events_url":"https://api.github.com/users/petschki/events{/privacy}","followers_url":"https://api.github.com/users/petschki/followers","following_url":"https://api.github.com/users/petschki/following{/other_user}","gists_url":"https://api.github.com/users/petschki/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/petschki","id":511761,"login":"petschki","node_id":"MDQ6VXNlcjUxMTc2MQ==","organizations_url":"https://api.github.com/users/petschki/orgs","received_events_url":"https://api.github.com/users/petschki/received_events","repos_url":"https://api.github.com/users/petschki/repos","site_admin":false,"starred_url":"https://api.github.com/users/petschki/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/petschki/subscriptions","type":"User","url":"https://api.github.com/users/petschki","user_view_type":"public"},"html_url":"https://github.com/collective/blicca.staticresourceoverride/commit/2fb0259a35fd83a9e50f2b38b3667f5056811359","node_id":"C_kwDOTSx1j9oAKDJmYjAyNTlhMzVmZDgzYTllNTBmMmIzOGIzNjY3ZjUwNTY4MTEzNTk","parents":[],"sha":"2fb0259a35fd83a9e50f2b38b3667f5056811359","url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/commits/2fb0259a35fd83a9e50f2b38b3667f5056811359"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/511761?v=4","events_url":"https://api.github.com/users/petschki/events{/privacy}","followers_url":"https://api.github.com/users/petschki/followers","following_url":"https:/