cca naming\n\nCo-Authored-By: Claude Fable 5 <noreply@anthropic.com>","tree":{"sha":"af5a646183b388b6d2dc8bdafb72daafbb2e4a91","url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/git/trees/af5a646183b388b6d2dc8bdafb72daafbb2e4a91"},"url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/git/commits/054583648a6f4792da944b6d6fdbc078850dcee2","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/511761?v=4","events_url":"https://api.github.com/users/petschki/events{/privacy}","followers_url":"https://api.github.com/users/petschki/followers","following_url":"https://api.github.com/users/petschki/following{/other_user}","gists_url":"https://api.github.com/users/petschki/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/petschki","id":511761,"login":"petschki","node_id":"MDQ6VXNlcjUxMTc2MQ==","organizations_url":"https://api.github.com/users/petschki/orgs","received_events_url":"https://api.github.com/users/petschki/received_events","repos_url":"https://api.github.com/users/petschki/repos","site_admin":false,"starred_url":"https://api.github.com/users/petschki/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/petschki/subscriptions","type":"User","url":"https://api.github.com/users/petschki","user_view_type":"public"},"html_url":"https://github.com/collective/blicca.staticresourceoverride/commit/054583648a6f4792da944b6d6fdbc078850dcee2","node_id":"C_kwDOTSx1j9oAKDA1NDU4MzY0OGE2ZjQ3OTJkYTk0NGI2ZDZmZGJjMDc4ODUwZGNlZTI","parents":[{"html_url":"https://github.com/collective/blicca.staticresourceoverride/commit/37408ec03dd56036ded77157b210cbde347a29fc","sha":"37408ec03dd56036ded77157b210cbde347a29fc","url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/commits/37408ec03dd56036ded77157b210cbde347a29fc"},{"html_url":"https://github.com/collective/blicca.s