 Claude Fable 5 <noreply@anthropic.com>","tree":{"sha":"0009ae4beacf258c0a028ec67f0cbb3ac73f143e","url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/git/trees/0009ae4beacf258c0a028ec67f0cbb3ac73f143e"},"url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/git/commits/0e5fdd899180bd7e4c138586e267e2468cbab3ca","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/511761?v=4","events_url":"https://api.github.com/users/petschki/events{/privacy}","followers_url":"https://api.github.com/users/petschki/followers","following_url":"https://api.github.com/users/petschki/following{/other_user}","gists_url":"https://api.github.com/users/petschki/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/petschki","id":511761,"login":"petschki","node_id":"MDQ6VXNlcjUxMTc2MQ==","organizations_url":"https://api.github.com/users/petschki/orgs","received_events_url":"https://api.github.com/users/petschki/received_events","repos_url":"https://api.github.com/users/petschki/repos","site_admin":false,"starred_url":"https://api.github.com/users/petschki/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/petschki/subscriptions","type":"User","url":"https://api.github.com/users/petschki","user_view_type":"public"},"html_url":"https://github.com/collective/blicca.staticresourceoverride/commit/0e5fdd899180bd7e4c138586e267e2468cbab3ca","node_id":"C_kwDOTSx1j9oAKDBlNWZkZDg5OTE4MGJkN2U0YzEzODU4NmUyNjdlMjQ2OGNiYWIzY2E","parents":[{"html_url":"https://github.com/collective/blicca.staticresourceoverride/commit/67bbc970cb83c5ac82daa34822a26e32d17bbfd2","sha":"67bbc970cb83c5ac82daa34822a26e32d17bbfd2","url":"https://api.github.com/repos/collective/blicca.staticresourceoverride/commits/67bbc970cb83c5ac82daa34822a26e32d17bbfd2"}],"sha":"0e5fdd899180bd7e4c138586e267e2468cbab3ca","url":"https://api.github.com/